"""Build reproducible artifacts for one validated kinetics run."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path

from scimodel.application.validate_kinetics import validate_csv
from scimodel.infrastructure.reproducibility import build_manifest


@dataclass(frozen=True)
class ReportArtifacts:
    """Paths generated by a report build."""

    report: Path
    manifest: Path
    fit_result: Path
    validation: Path

    def to_dict(self) -> dict[str, str]:
        return {
            "report": str(self.report),
            "manifest": str(self.manifest),
            "fit_result": str(self.fit_result),
            "validation": str(self.validation),
        }


def build_csv_report(
    input_path: Path,
    output_dir: Path,
    *,
    x_column: str = "substrate_conc",
    y_column: str = "reaction_velocity",
) -> tuple[ReportArtifacts, bool]:
    """Fit, validate, and write a reproducible report bundle."""
    result, validation = validate_csv(input_path, x_column=x_column, y_column=y_column)
    output_dir.mkdir(parents=True, exist_ok=True)
    configuration = {"x_column": x_column, "y_column": y_column, "model": result.model}
    manifest = build_manifest(
        input_path,
        command="report build",
        configuration=configuration,
    )
    fit_path = output_dir / "fit_result.json"
    validation_path = output_dir / "validation.json"
    manifest_path = output_dir / "run_manifest.json"
    report_path = output_dir / "report.md"
    _write_json(fit_path, result.to_dict())
    _write_json(validation_path, validation.to_dict())
    _write_json(manifest_path, manifest)
    report_path.write_text(
        _render_markdown(input_path, result.to_dict(), validation.to_dict(), manifest),
        encoding="utf-8",
    )
    return ReportArtifacts(report_path, manifest_path, fit_path, validation_path), validation.valid


def _write_json(path: Path, value: dict[str, object]) -> None:
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def _render_markdown(
    input_path: Path,
    result: dict[str, object],
    validation: dict[str, object],
    manifest: dict[str, object],
) -> str:
    parameters = result["parameters"]
    metrics = result["metrics"]
    vmax_interval = result["confidence_intervals"]["vmax"]
    km_interval = result["confidence_intervals"]["km"]
    vmax_se = result["standard_errors"]["vmax"]
    km_se = result["standard_errors"]["km"]
    parameter_rows = (
        f"| Vmax | {parameters['vmax']:.8g} | {vmax_se:.8g} | "
        f"[{vmax_interval[0]:.8g}, {vmax_interval[1]:.8g}] |\n"
        f"| Km | {parameters['km']:.8g} | {km_se:.8g} | "
        f"[{km_interval[0]:.8g}, {km_interval[1]:.8g}] |"
    )
    checks = validation["checks"]
    warnings = validation["warnings"]
    return (
        f"""# SciModel Validation Report

## Run summary

- **Input:** `{input_path}`
- **Model:** `{result["model"]}`
- **Status:** `{result["status"]}`
- **Reproducibility manifest:** `run_manifest.json`

## Data quality

```json
{json.dumps(validation["data_quality"], indent=2, sort_keys=True)}
```

## Parameter estimates

| Parameter | Estimate | Standard error | 95% confidence interval |
|---|---:|---:|---:|
{parameter_rows}

## Fit metrics

- RSS: `{metrics["rss"]:.8g}`
- RMSE: `{metrics["rmse"]:.8g}`
- R²: `{metrics["r_squared"]:.8g}`
- Function evaluations: `{result["function_evaluations"]}`

## Validation checks

| Check | Result | Message |
|---|---|---|
"""
        + "\n".join(
            f"| {check['name']} | {'PASS' if check['passed'] else 'FAIL'} | {check['message']} |"
            for check in checks  # type: ignore[union-attr]
        )
        + f"""

## Diagnostics

```json
{json.dumps(validation["diagnostics"], indent=2, sort_keys=True)}
```

## Warnings and limitations

"""
        + (
            "\n".join(f"- {warning}" for warning in warnings)
            if warnings
            else "No warnings generated."
        )
        + "\n\n### Model assumptions\n\n"
        + "\n".join(f"- {assumption}" for assumption in validation["assumptions"])
        + "\n\n### Known limitations\n\n"
        + "\n".join(f"- {limitation}" for limitation in validation["limitations"])
        + """

This report describes the fitted model and validation checks. It does not establish that
the model is physically correct for every experiment or domain.

## Reproduction

The input SHA-256, configuration, software version, Python version, and platform are
recorded in `run_manifest.json`.
"""
    )
